              </svg>

              {/* X-Axis Month Labels */}
              <div className="absolute -bottom-6 inset-x-0 flex justify-between">
                {months.map((m) => (
                  <span key={m} className="text-[11px] font-semibold text-slate-500">
                    {m}
                  </span>
                ))}
              </div>
            </div>
          </div>

          {/* Legend */}
          <div className="flex items-center justify-center gap-6 mt-8 pt-2">
            <div className="flex items-center gap-2">
              <span className="w-5 h-2.5 rounded-sm border-2 border-[#10B981] bg-[#10B981]/20" />
              <span className="text-xs font-semibold text-slate-600">Total Income</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="w-5 h-2.5 rounded-sm border-2 border-[#EF4444] bg-[#EF4444]/20" />
              <span className="text-xs font-semibold text-slate-600">Total Expenses</span>
            </div>
          </div>
        </div>
      </section>

    </main>
  );
};

export default AdminDashboard;
